const DB_NAME='sterbefall_assistent_db', DB_VERSION=5;
let db;
const state={route:'welcome',persons:[],activePersonId:null,cases:[],settings:{simpleMode:true},editPersonId:null,docKey:null,officialPdfKey:null};

const OFFICIAL={
  vorsorge:'https://www.bmj.de/SharedDocs/Downloads/DE/Formular/Vorsorgevollmacht.html',
  betreuung:'https://www.bmj.de/SharedDocs/Downloads/DE/Formular/Betreuungsverfuegung.html',
  patienten:'https://www.bmj.de/DE/service/formulare/form_patientenverfuegung/form_patientenverfuegung_node.html',
  patientenInfo:'https://www.bmj.de/DE/themen/vorsorge_betreuungsrecht/patientenverfuegung/patientenverfuegung_node.html',
  zvr:'https://www.vorsorgeregister.de/privatpersonen/registrierung',
  zvrForms:'https://www.vorsorgeregister.de/formulare',
  organspende:'https://organspende-register.de/'
};

const OFFICIAL_PDFS={
  vorsorge:{title:'Vorsorgevollmacht - lokale Blanko-PDF',local:'forms/vorsorgevollmacht.pdf',url:'https://www.bmj.de/SharedDocs/Downloads/DE/Formular/Vorsorgevollmacht.html',source:'Lokale App-Vorlage; Abgleich: Bundesministerium der Justiz',stand:'App-Vorlage 09/2026'},
  patienten:{title:'Patientenverfügung - lokale Blanko-PDF',local:'forms/patientenverfuegung.pdf',url:'https://www.bmj.de/DE/service/formulare/form_patientenverfuegung/form_patientenverfuegung_node.html',source:'Lokale App-Vorlage; Abgleich: BMJ-Textbausteine',stand:'App-Vorlage 09/2026'},
  betreuung:{title:'Betreuungsverfügung - lokale Blanko-PDF',local:'forms/betreuungsverfuegung.pdf',url:'https://www.bmj.de/SharedDocs/Downloads/DE/Formular/Betreuungsverfuegung.html',source:'Lokale App-Vorlage; Abgleich: Bundesministerium der Justiz',stand:'App-Vorlage 09/2026'},
  bank:{title:'Bankvollmacht - lokale Blanko-PDF',local:'forms/bankvollmacht.pdf',url:'https://www.bmj.de/SharedDocs/Publikationen/DE/Betreuungsrecht.html',source:'Lokale App-Vorlage; Banken können eigene Formulare verlangen',stand:'App-Vorlage 09/2026'},
  schweigepflicht:{title:'Schweigepflichtentbindung - lokale Blanko-PDF',local:'forms/schweigepflichtentbindung.pdf',url:'https://www.bmj.de/DE/themen/vorsorge_betreuungsrecht/vorsorgevollmacht/vorsorgevollmacht_node.html',source:'Lokale App-Vorlage',stand:'App-Vorlage 09/2026'},
  bestattung:{title:'Bestattungswünsche - lokale Blanko-PDF',local:'forms/bestattungswuensche.pdf',url:'https://www.bmj.de/',source:'Lokale App-Vorlage',stand:'App-Vorlage 09/2026'},
  organe:{title:'Organspende-Entscheidung - lokale Blanko-PDF',local:'forms/organspende-entscheidung.pdf',url:'https://organspende-register.de/',source:'Lokale App-Vorlage; offizielles Register separat',stand:'App-Vorlage 09/2026'},
  testament:{title:'Testament - Vorbereitungsblatt',local:'forms/testament-vorbereitungsblatt.pdf',url:'https://www.bmj.de/',source:'Lokales Vorbereitungsblatt - kein Testament',stand:'App-Vorlage 09/2026'},
  zvrP:{title:'ZVR Formular P - lokale Arbeitskopie',local:'forms/zvr-formular-p.pdf',url:'https://www.vorsorgeregister.de/formulare',source:'Arbeitskopie nach ZVR Formular P; aktuelle Originalfassung vor Einreichung prüfen',stand:'ZVR-Bezug 01.02.2024'}
};

const DOCS={
  vorsorge:{title:'Vorsorgevollmacht',desc:'Wer darf handeln, wenn die Person es selbst nicht kann?',icon:'🤝',official:'vorsorge',important:true},
  patienten:{title:'Patientenverfügung',desc:'Konkrete medizinische Wünsche für den Fall eigener Entscheidungsunfähigkeit.',icon:'🩺',official:'patienten',important:true},
  betreuung:{title:'Betreuungsverfügung',desc:'Wunschperson für den Fall einer gerichtlichen Betreuung.',icon:'⚖️',official:'betreuung',important:true},
  bank:{title:'Bankvollmacht',desc:'Kontozugriff und Bankangelegenheiten im Bedarfsfall klären.',icon:'🏦',important:true},
  schweigepflicht:{title:'Schweigepflichtentbindung',desc:'Festhalten, wer medizinische Informationen erhalten darf.',icon:'🔐',important:true},
  testament:{title:'Testament / Erbregelung',desc:'Status und Aufbewahrungsort einer erbrechtlichen Regelung.',icon:'📜'},
  bestattung:{title:'Bestattungswünsche',desc:'Bestattungsart, Ort, Trauerfeier und persönliche Wünsche.',icon:'🕯️'},
  organe:{title:'Organspende-Entscheidung',desc:'Eigene Entscheidung dokumentieren und Auffindbarkeit sichern.',icon:'❤️',official:'organspende'}
};
const RELATIONS={self:'Ich',partner:'Partner/in',mother:'Mutter',father:'Vater',child:'Kind',sibling:'Geschwister',other:'Andere Person'};

function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;['profile','case','docs','settings','persons','cases','meta','templates'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s)});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function idbGet(store,key){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function idbSet(store,key,val){return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(val,key);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function fmtDate(v){if(!v)return '';const d=new Date(v+'T00:00:00');return isNaN(d)?v:d.toLocaleDateString('de-DE')}
function uid(prefix='id'){return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`}
function toast(msg){const t=document.getElementById('toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
function activePerson(){return state.persons.find(p=>p.id===state.activePersonId)||null}
function personName(p){return p?[p.profile?.firstName,p.profile?.lastName].filter(Boolean).join(' ')||'Unbenannte Person':'Keine Person gewählt'}
function relationLabel(v){return RELATIONS[v]||'Angehörige/r'}
function relationEmoji(r){return ({self:'👤',partner:'❤️',mother:'👵',father:'👴',child:'🧒',sibling:'🧑',other:'👥'})[r]||'👤'}
function normalizePerson(p){p.profile=p.profile||{};p.contacts=p.contacts||p.emergencyContacts||[];delete p.emergencyContacts;p.medical=p.medical||{};p.zvr=p.zvr||{};p.bestattung=p.bestattung||{};p.digital=p.digital||{};p.documents=p.documents||{};for(const k of Object.keys(DOCS)){const v=p.documents[k];if(typeof v==='boolean')p.documents[k]={status:v?'available':'missing'};else if(!v)p.documents[k]={status:'missing'};}return p}
function docStatus(p,k){return normalizePerson(p).documents[k]?.status||'missing'}
function isDocDone(p,k){return ['available','registered'].includes(docStatus(p,k))}
function completion(p=activePerson()){
 if(!p)return 0;normalizePerson(p);const x=p.profile||{};
 const base=['firstName','lastName','birthDate','street','zip','city','phone','healthInsurance'].filter(k=>x[k]).length/8;
 const important=['vorsorge','patienten','betreuung','bank','schweigepflicht'].filter(k=>isDocDone(p,k)).length/5;
 const contacts=(p.contacts||[]).length?1:0;
 const zvr=p.zvr?.registered?1:0;
 const wishes=(p.bestattung?.type||p.bestattung?.notes||isDocDone(p,'bestattung'))?1:0;
 return Math.round((base*.25+important*.45+contacts*.12+zvr*.10+wishes*.08)*100);
}
function appTop(title,sub=''){return `<div class="topbar"><button class="cta ghost back-btn" onclick="back()">‹</button><div class="grow"><h1>${esc(title)}</h1>${sub?`<div class="sub">${esc(sub)}</div>`:''}</div></div>`}
const nav=()=>`<nav class="bottom-nav no-print"><button class="nav-btn ${state.route==='home'?'active':''}" onclick="go('home')"><span class="ni">⌂</span>Start</button><button class="nav-btn ${['documents','document-detail'].includes(state.route)?'active':''}" onclick="go('documents')"><span class="ni">▤</span>Dokumente</button><button class="nav-btn ${state.route==='case'?'active':''}" onclick="go('case')"><span class="ni">◷</span>Sterbefall</button><button class="nav-btn ${['profile','backup'].includes(state.route)?'active':''}" onclick="go('profile')"><span class="ni">●</span>Profil</button></nav>`;
function go(r){state.route=r;render();window.scrollTo(0,0)}
function back(){const map={'person-edit':'vorsorge','vorsorge-person':'vorsorge','profile':'vorsorge-person','trusted':'vorsorge-person','documents':'vorsorge-person','document-detail':'documents','form-fill':'document-detail','official-pdf':state.officialPdfKey==='zvrP'?'zvr':'document-detail','medical':'vorsorge-person','zvr':'vorsorge-person','bestattung':'vorsorge-person','digital':'vorsorge-person','serious':'home','case':'home','generator':'case','backup':'profile'};go(map[state.route]||'home')}
function render(){const a=document.getElementById('app');let html='';const r=state.route;if(r==='welcome')html=welcome();else if(r==='home')html=home()+nav();else if(r==='vorsorge')html=vorsorgePeople()+nav();else if(r==='vorsorge-person')html=vorsorgePerson()+nav();else if(r==='person-edit')html=personEdit()+nav();else if(r==='profile')html=profile()+nav();else if(r==='trusted')html=trusted()+nav();else if(r==='documents')html=documents()+nav();else if(r==='document-detail')html=documentDetail()+nav();else if(r==='form-fill')html=formFill()+nav();else if(r==='official-pdf')html=officialPdfScreen()+nav();else if(r==='medical')html=medical()+nav();else if(r==='zvr')html=zvr()+nav();else if(r==='bestattung')html=bestattung()+nav();else if(r==='digital')html=digital()+nav();else if(r==='emergency')html=emergency();else if(r==='serious')html=serious()+nav();else if(r==='case')html=caseScreen()+nav();else if(r==='generator')html=generator()+nav();else if(r==='backup')html=backup()+nav();a.innerHTML=html;}
function noPerson(title){return `<section class="screen">${appTop(title)}<div class="content"><div class="empty-card"><div class="empty-icon">👥</div><h3>Noch keine Person ausgewählt</h3><p>Lege in der Vorsorge zuerst eine Person an.</p><button class="cta teal full" onclick="go('vorsorge')">Zur Vorsorge</button></div></div></section>`}
function personSwitch(p){return `<button class="person-switch" onclick="go('vorsorge')"><span>${relationEmoji(p.relation)} ${esc(personName(p))}</span><small>${esc(relationLabel(p.relation))} · Person wechseln</small></button>`}
function field(label,key,val='',type='text',hint=''){return `<div class="field"><label>${esc(label)}</label><input type="${type}" id="${key}" value="${esc(val||'')}" />${hint?`<small>${esc(hint)}</small>`:''}</div>`}
function textareaField(label,key,val='',hint=''){return `<div class="field"><label>${esc(label)}</label><textarea id="${key}" rows="4">${esc(val||'')}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</div>`}
function selectField(label,key,val,opts){return `<div class="field"><label>${esc(label)}</label><select id="${key}">${opts.map(o=>{const [v,l]=String(o).includes('|')?String(o).split('|'):[o,o||'Bitte auswählen'];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
function task(title,done,meta,route){return `<button class="list-item ${done?'done':''}" onclick="go('${route}')"><div class="dot">${done?'✓':''}</div><div class="grow"><b>${esc(title)}</b><div class="meta">${esc(meta)}</div></div><div class="chev">›</div></button>`}
function openOfficial(k){const u=OFFICIAL[k];if(u)window.open(u,'_blank','noopener')}

function welcome(){return `<section class="screen"><div class="hero"><div class="hero-badge">🤲</div><h1>Sterbefall<br>Assistent</h1><p>Vorsorge, schwere Erkrankung und Sterbefall – verständlich, Schritt für Schritt und local first.</p><button class="cta" onclick="go('home')">Jetzt starten →</button></div><div class="content"><div class="notice"><b>Local first:</b> Persönliche Daten werden standardmäßig nur in diesem Browser auf diesem Gerät gespeichert.</div></div></section>`}
function home(){const p=activePerson();return `<section class="screen">${appTop('Willkommen','Was möchten Sie tun?')}<div class="content">${p?`<div class="active-summary"><span>${relationEmoji(p.relation)}</span><div class="grow"><small>Aktive Person</small><b>${esc(personName(p))}</b></div><button onclick="go('vorsorge')">Wechseln</button></div>`:''}<div class="grid-menu"><button class="menu-card" onclick="go('vorsorge')"><div class="icon">🌿</div><div><h3>Vorsorge</h3><p>Personen, Vollmachten, Wünsche und Notfallinformationen</p></div><div class="arrow">›</div></button><button class="menu-card yellow" onclick="go('serious')"><div class="icon">❤</div><div><h3>Schwere Erkrankung</h3><p>Was jetzt vorbereitet und geklärt werden sollte</p></div><div class="arrow">›</div></button><button class="menu-card" onclick="go('case')"><div class="icon">🕯</div><div><h3>Sterbefall</h3><p>Geführte Fallakte und nächste Schritte</p></div><div class="arrow">›</div></button><button class="menu-card yellow" onclick="go('documents')"><div class="icon">📄</div><div><h3>Dokumente</h3><p>Dokumentstatus und offizielle Formulare</p></div><div class="arrow">›</div></button></div><div class="section-title"><h2>Schnellzugriff</h2></div><div class="row"><button class="cta teal full" onclick="go('emergency')">🚨 Notfallkarte</button><button class="cta ghost full" onclick="go('backup')">💾 Datensicherung</button></div></div></section>`}

function vorsorgePeople(){const cards=state.persons.length?state.persons.map(personCard).join(''):`<div class="empty-card"><div class="empty-icon">👥</div><h3>Noch keine Person angelegt</h3><p>Lege dich selbst oder einen Angehörigen an.</p></div>`;return `<section class="screen">${appTop('Vorsorge','Für Sie selbst und Angehörige')}<div class="content"><div class="section-title"><h2>Für wen möchten Sie vorsorgen?</h2></div><div class="person-grid">${cards}</div><button class="cta full" style="margin-top:14px" onclick="newPerson()">＋ Person hinzufügen</button><div class="notice" style="margin-top:14px">Jede Person besitzt einen eigenen Vorsorgestatus, eigene Unterlagen und eigene Notfallinformationen.</div></div></section>`}
function personCard(p){const pct=completion(p);return `<div class="person-card ${p.id===state.activePersonId?'selected':''}"><button class="person-main" onclick="selectPerson('${p.id}')"><div class="avatar">${relationEmoji(p.relation)}</div><div class="grow"><b>${esc(personName(p))}</b><div class="small muted">${esc(relationLabel(p.relation))}</div><div class="person-progress"><span style="width:${pct}%"></span></div><div class="small">Vorsorge ${pct}%</div></div><div class="chev">›</div></button><div class="person-actions"><button onclick="editPerson('${p.id}')">Bearbeiten</button><button class="danger-link" onclick="deletePerson('${p.id}')">Löschen</button></div></div>`}
function newPerson(){state.editPersonId=null;go('person-edit')}
function editPerson(id){state.editPersonId=id;go('person-edit')}
async function selectPerson(id){state.activePersonId=id;await saveMeta();go('vorsorge-person')}
async function deletePerson(id){const p=state.persons.find(x=>x.id===id);if(!p||!confirm(`${personName(p)} wirklich löschen? Alle lokalen Vorsorgedaten dieser Person werden gelöscht.`))return;state.persons=state.persons.filter(x=>x.id!==id);state.cases=state.cases.filter(c=>c.personId!==id);if(state.activePersonId===id)state.activePersonId=state.persons[0]?.id||null;await persistAll();toast('Person gelöscht');render()}
function personEdit(){const p=state.editPersonId?state.persons.find(x=>x.id===state.editPersonId):null,x=p?.profile||{};return `<section class="screen">${appTop(p?'Person bearbeiten':'Person hinzufügen','Nur wenige Angaben zum Start')}<div class="content"><div class="form-card"><h3>Grunddaten</h3>${selectField('Beziehung','personRelation',p?.relation||'other',['self|Ich','partner|Partner/in','mother|Mutter','father|Vater','child|Kind','sibling|Geschwister','other|Andere Person'])}${field('Vorname','personFirst',x.firstName)}${field('Nachname','personLast',x.lastName)}${field('Geburtsdatum','personBirth',x.birthDate,'date')}</div><button class="cta teal full" onclick="savePersonBasic()">${p?'Änderungen speichern':'Person anlegen'}</button></div></section>`}
async function savePersonBasic(){const relation=document.getElementById('personRelation').value,firstName=document.getElementById('personFirst').value.trim(),lastName=document.getElementById('personLast').value.trim(),birthDate=document.getElementById('personBirth').value;if(!firstName||!lastName){toast('Vor- und Nachname bitte ausfüllen');return}if(state.editPersonId){const p=state.persons.find(x=>x.id===state.editPersonId);p.relation=relation;p.profile={...(p.profile||{}),firstName,lastName,birthDate};normalizePerson(p)}else{const p=normalizePerson({id:uid('person'),relation,profile:{firstName,lastName,birthDate}});state.persons.push(p);state.activePersonId=p.id}await persistPersons();state.editPersonId=null;toast('Person gespeichert');go('vorsorge')}

function moduleCard(icon,title,desc,meta,route,done=false){return `<button class="module-card ${done?'complete':''}" onclick="go('${route}')"><div class="module-icon">${icon}</div><div class="grow"><b>${esc(title)}</b><p>${esc(desc)}</p>${meta?`<small>${esc(meta)}</small>`:''}</div><div class="chev">›</div></button>`}
function vorsorgePerson(){const p=activePerson();if(!p)return noPerson('Vorsorge');const pct=completion(p);normalizePerson(p);const x=p.profile;const docsDone=Object.keys(DOCS).filter(k=>isDocDone(p,k)).length;return `<section class="screen">${appTop('Vorsorge',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}<div class="progress-card"><div class="progress-ring" style="--p:${pct}"><div style="text-align:center"><b>${pct}%</b><br><span>vorbereitet</span></div></div><p class="muted center">Die wichtigsten Angaben werden nur einmal erfasst und in den Bereichen wiederverwendet.</p></div><div class="section-title"><h2>Vorsorge-Bereiche</h2></div><div class="module-list">${moduleCard('👤','Stammdaten','Adresse, Versicherung und wichtige Kennnummern',x.street?'Stammdaten teilweise erfasst':'Noch ergänzen','profile',!!x.street)}${moduleCard('👥','Vertrauenspersonen','Bevollmächtigte und Notfallkontakte',(p.contacts||[]).length?`${p.contacts.length} Kontakt(e)`:'Noch keine Kontakte','trusted',(p.contacts||[]).length>0)}${moduleCard('📄','Dokumente & Vollmachten','Vorsorgevollmacht, Patientenverfügung, Bankvollmacht …',`${docsDone} von ${Object.keys(DOCS).length} dokumentiert`,'documents',docsDone>=5)}${moduleCard('🩺','Medizin & Krankenhaus','Hausarzt, wichtige Hinweise, Organspende und Auffindbarkeit',p.medical?.doctorName?'Hausarzt hinterlegt':'Noch ergänzen','medical',!!p.medical?.doctorName)}${moduleCard('🏛️','Zentrales Vorsorgeregister','Registrierung und Aufbewahrungsort dokumentieren',p.zvr?.registered?'Als registriert markiert':'Noch nicht registriert','zvr',!!p.zvr?.registered)}${moduleCard('🕯️','Bestattungswünsche','Wünsche festhalten, damit Angehörige nicht raten müssen',p.bestattung?.type||p.bestattung?.notes?'Wünsche vorhanden':'Noch offen','bestattung',!!(p.bestattung?.type||p.bestattung?.notes))}${moduleCard('🔑','Digitaler Nachlass','Konten, Geräte und Zugangshinweise – ohne Passwörter im Klartext',p.digital?.contactName?'Vertrauensperson hinterlegt':'Noch offen','digital',!!p.digital?.contactName)}</div><div class="notice" style="margin-top:16px"><b>Hinweis:</b> Die App ersetzt keine medizinische oder rechtliche Beratung. Bei rechtlich relevanten Dokumenten verlinkt sie bevorzugt auf offizielle Formulare und Informationen.</div></div></section>`}

function profile(){const p=activePerson();if(!p)return noPerson('Stammdaten');const x=p.profile||{};return `<section class="screen">${appTop('Stammdaten',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}<div class="form-card"><h3>Persönliche Daten</h3><div class="two">${field('Vorname','firstName',x.firstName)}${field('Nachname','lastName',x.lastName)}</div><div class="two">${field('Geburtsdatum','birthDate',x.birthDate,'date')}${selectField('Familienstand','maritalStatus',x.maritalStatus||'',['|Bitte auswählen','ledig','verheiratet','geschieden','verwitwet','Lebenspartnerschaft'])}</div></div><div class="form-card"><h3>Kontakt & Adresse</h3>${field('Straße / Hausnummer','street',x.street)}<div class="two">${field('PLZ','zip',x.zip)}${field('Ort','city',x.city)}</div><div class="two">${field('Telefon','phone',x.phone,'tel')}${field('E-Mail','email',x.email,'email')}</div></div><div class="form-card"><h3>Versicherung & Identifikation</h3>${field('Krankenkasse','healthInsurance',x.healthInsurance)}${field('Versichertennummer','healthInsuranceNo',x.healthInsuranceNo)}${field('Rentenversicherungsnummer','pensionNo',x.pensionNo)}${field('Steuer-ID','taxId',x.taxId,'text','Optional – nur speichern, wenn gewünscht.')}</div><button class="cta teal full" onclick="saveProfile()">Speichern</button><button class="cta ghost full mt10" onclick="go('backup')">Datensicherung & Export</button></div></section>`}
async function saveProfile(){const p=activePerson();if(!p)return;['firstName','lastName','birthDate','maritalStatus','street','zip','city','phone','email','healthInsurance','healthInsuranceNo','pensionNo','taxId'].forEach(k=>p.profile[k]=document.getElementById(k)?.value?.trim()||'');await persistPersons();toast('Stammdaten lokal gespeichert');render()}

function trusted(){const p=activePerson();if(!p)return noPerson('Vertrauenspersonen');const list=(p.contacts||[]).map((c,i)=>`<div class="contact-card"><div class="avatar small-avatar">${c.isEmergency?'🚨':'👤'}</div><div class="grow"><b>${esc(c.name||'Unbenannt')}</b><div class="small muted">${esc(c.role||'Vertrauensperson')}</div><div class="small">${esc(c.phone||'Keine Telefonnummer')}</div></div><button class="danger-link" onclick="removeContact(${i})">Entfernen</button></div>`).join('');return `<section class="screen">${appTop('Vertrauenspersonen',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}${list||'<div class="empty-card"><div class="empty-icon">👥</div><h3>Noch keine Vertrauensperson</h3><p>Hinterlege mindestens einen gut erreichbaren Kontakt.</p></div>'}<div class="form-card"><h3>Kontakt hinzufügen</h3>${field('Name','contactName','')}${field('Beziehung / Rolle','contactRole','')}${field('Telefon','contactPhone','','tel')}${field('E-Mail','contactEmail','','email')}<label class="checkline"><input type="checkbox" id="contactEmergency" checked> Als Notfallkontakt anzeigen</label><label class="checkline"><input type="checkbox" id="contactAgent"> Als bevollmächtigte Vertrauensperson markieren</label><button class="cta teal full" onclick="addContact()">＋ Kontakt hinzufügen</button></div></div></section>`}
async function addContact(){const p=activePerson(),name=document.getElementById('contactName').value.trim();if(!name){toast('Bitte einen Namen eingeben');return}p.contacts=p.contacts||[];p.contacts.push({id:uid('contact'),name,role:document.getElementById('contactRole').value.trim(),phone:document.getElementById('contactPhone').value.trim(),email:document.getElementById('contactEmail').value.trim(),isEmergency:document.getElementById('contactEmergency').checked,isAgent:document.getElementById('contactAgent').checked});await persistPersons();toast('Kontakt hinzugefügt');render()}
async function removeContact(i){const p=activePerson();if(!p||!confirm('Kontakt entfernen?'))return;p.contacts.splice(i,1);await persistPersons();render()}

function documents(){const p=activePerson();if(!p)return noPerson('Dokumente');normalizePerson(p);return `<section class="screen">${appTop('Dokumente & Vollmachten',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}${Object.entries(DOCS).map(([k,d])=>docRow(p,k,d)).join('')}<div class="notice" style="margin-top:14px">„Vorhanden“ bedeutet hier nur, dass du den Status dokumentiert hast. Die App prüft nicht automatisch, ob ein Dokument rechtlich wirksam, aktuell oder vollständig ist.</div></div></section>`}
function docRow(p,k,d){const s=docStatus(p,k),label={missing:'Noch nicht vorhanden',draft:'In Vorbereitung',available:'Vorhanden',registered:'Vorhanden / registriert'}[s]||s;return `<button class="doc-row full-button" onclick="openDoc('${k}')"><div class="doc-icon">${d.icon}</div><div class="grow"><b>${esc(d.title)}</b><div class="small muted">${esc(d.desc)}</div><div class="status ${s==='missing'?'warn':''}">${s==='missing'?'○':'✓'} ${esc(label)}</div></div><div class="chev">›</div></button>`}
function openDoc(k){state.docKey=k;go('document-detail')}
function documentDetail(){const p=activePerson();if(!p)return noPerson('Dokument');const k=state.docKey||'vorsorge',d=DOCS[k],obj=normalizePerson(p).documents[k]||{};const directLabel=k==='testament'?'Vorbereitungsblatt ausfüllen':'Formular direkt ausfüllen';return `<section class="screen">${appTop(d.title,`Für ${personName(p)}`)}<div class="content"><div class="info-card"><div class="big-icon">${d.icon}</div><h2>${esc(d.title)}</h2><p>${esc(d.desc)}</p></div><button class="cta teal full" onclick="go('form-fill')">✍ ${directLabel}</button>${OFFICIAL_PDFS[k]?`<button class="cta ghost full mt10" onclick="openOfficialPdf('${k}')">📄 Lokale Blanko-PDF automatisch befüllen</button>`:''}<div class="notice mt10"><b>Automatische Datenübernahme:</b> Bereits hinterlegte Personen-, Adress- und Kontaktdaten werden im Formular automatisch eingesetzt. Nur fehlende Angaben werden noch abgefragt.</div><div class="form-card mt16"><h3>Status & Ablage</h3>${selectField('Dokumentstatus','docStatus',obj.status||'missing',['missing|Noch nicht vorhanden','draft|In Vorbereitung','available|Vorhanden','registered|Vorhanden / registriert'])}${field('Datum / letzte Aktualisierung','docDate',obj.date||'','date')}${field('Aufbewahrungsort','docStorage',obj.storageLocation||'','text','Zum Beispiel: roter Ordner im Arbeitszimmer, Notar, Bankschließfach.')}${textareaField('Notizen','docNotes',obj.notes||'')}<button class="cta ghost full" onclick="saveDocumentDetail()">Status speichern</button></div>${d.official?`<div class="official-card"><b>Offizielle Quelle zum Gegenprüfen</b><p>Das direkt ausgefüllte App-Dokument kann hier mit den amtlichen Informationen bzw. Formularen abgeglichen werden.</p><button class="cta ghost full" onclick="openOfficial('${d.official}')">Offizielle Seite öffnen ↗</button></div>`:''}${k==='patienten'?`<div class="notice"><b>Patientenverfügung:</b> Die App erstellt einen strukturierten Entwurf aus den ausgewählten Festlegungen. Vor Unterschrift sollten die Angaben sorgfältig geprüft und bei Unsicherheit ärztlich oder rechtlich besprochen werden.</div>`:''}${k==='testament'?`<div class="notice"><b>Testament:</b> Die App erzeugt hier bewusst nur ein Vorbereitungsblatt. Ein ausgedruckter, am Computer erzeugter Text ist nicht automatisch ein wirksames eigenhändiges Testament.</div>`:''}</div></section>`}
async function saveDocumentDetail(){const p=activePerson(),k=state.docKey;if(!p||!k)return;p.documents[k]={status:document.getElementById('docStatus').value,date:document.getElementById('docDate').value,storageLocation:document.getElementById('docStorage').value.trim(),notes:document.getElementById('docNotes').value.trim()};await persistPersons();toast('Dokumentstatus gespeichert');render()}


function contactOptions(p,selected=''){const cs=p.contacts||[];return `<option value="">Bitte auswählen / manuell eingeben</option>`+cs.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}${c.role?` – ${esc(c.role)}`:''}</option>`).join('')}
function commonIdentityFields(p){const x=p.profile||{};return `<div class="form-card"><h3>Person</h3><div class="autofill-badge">✓ aus Stammdaten übernommen</div><div class="two">${field('Vorname','ffFirst',x.firstName)}${field('Nachname','ffLast',x.lastName)}</div>${field('Geburtsdatum','ffBirth',x.birthDate,'date')}${field('Straße / Hausnummer','ffStreet',x.street)}<div class="two">${field('PLZ','ffZip',x.zip)}${field('Ort','ffCity',x.city)}</div></div>`}
function agentFields(p,fd={}){return `<div class="form-card"><h3>Vertrauensperson / Bevollmächtigte Person</h3><div class="field"><label>Aus vorhandenen Kontakten übernehmen</label><select id="ffContact" onchange="applyFormContact()">${contactOptions(p,fd.contactId||'')}</select></div><div class="two">${field('Name','ffAgentName',fd.agentName||'')}${field('Beziehung / Rolle','ffAgentRole',fd.agentRole||'')}</div><div class="two">${field('Telefon','ffAgentPhone',fd.agentPhone||'','tel')}${field('E-Mail','ffAgentEmail',fd.agentEmail||'','email')}</div>${field('Anschrift','ffAgentAddress',fd.agentAddress||'')}</div>`}
function formFill(){const p=activePerson();if(!p)return noPerson('Formular');const k=state.docKey||'vorsorge',d=DOCS[k],obj=normalizePerson(p).documents[k]||{},fd=obj.formData||{};let body='';if(k==='vorsorge')body=formVorsorge(p,fd);else if(k==='patienten')body=formPatienten(p,fd);else if(k==='betreuung')body=formBetreuung(p,fd);else if(k==='bank')body=formBank(p,fd);else if(k==='schweigepflicht')body=formSchweigepflicht(p,fd);else if(k==='bestattung')body=formBestattung(p,fd);else if(k==='organe')body=formOrgane(p,fd);else if(k==='testament')body=formTestament(p,fd);return `<section class="screen form-fill-page">${appTop(d.title,`Direkt ausfüllen für ${personName(p)}`)}<div class="content"><div class="notice"><b>Automatisch vorausgefüllt:</b> Stammdaten werden übernommen. Änderungen hier gelten zunächst nur für dieses Formular und überschreiben die Stammdaten nicht.</div>${body}<div class="row mt16 no-print"><button class="cta teal full" onclick="saveFilledForm()">Speichern</button><button class="cta ghost full" onclick="refreshFormPreview()">Vorschau</button></div><button class="cta full mt10 no-print" onclick="printFilledForm()">🖨 Drucken / als PDF speichern</button><div id="formPreview" class="print-document">${renderFilledDocument(k,p,fd)}</div></div></section>`}
function formVorsorge(p,fd){return `${commonIdentityFields(p)}${agentFields(p,fd)}<div class="form-card"><h3>Umfang der Vollmacht</h3>${checkLine('ffHealth','Gesundheitssorge und Pflege',fd.health)}${checkLine('ffResidence','Aufenthalt und Wohnungsangelegenheiten',fd.residence)}${checkLine('ffAssets','Vermögensangelegenheiten',fd.assets)}${checkLine('ffAuthorities','Behörden, Versicherungen und Sozialleistungsträger',fd.authorities)}${checkLine('ffPost','Post, Telekommunikation und digitale Kommunikation',fd.post)}${checkLine('ffDigital','Digitaler Nachlass und Online-Konten',fd.digital)}${checkLine('ffCourt','Vertretung gegenüber Gerichten im zulässigen Umfang',fd.court)}${selectField('Geltung über den Tod hinaus','ffAfterDeath',fd.afterDeath||'no',['no|Nein','yes|Ja','unsure|Noch offen'])}${textareaField('Besondere Wünsche / Einschränkungen','ffNotes',fd.notes||'')}</div>`}
function formPatienten(p,fd){return `${commonIdentityFields(p)}<div class="form-card"><h3>Situationen, in denen die Verfügung gelten soll</h3>${textareaField('Konkrete Situationen','ffSituations',fd.situations||'','Beschreibe möglichst konkret die Situationen, in denen die Festlegungen gelten sollen.')}</div><div class="form-card"><h3>Ärztliche und pflegerische Maßnahmen</h3>${choiceField('Schmerz- und Symptombehandlung','ffPain',fd.pain)}${choiceField('Wiederbelebung','ffResuscitation',fd.resuscitation)}${choiceField('Künstliche Beatmung','ffVentilation',fd.ventilation)}${choiceField('Künstliche Ernährung','ffNutrition',fd.nutrition)}${choiceField('Künstliche Flüssigkeitszufuhr','ffHydration',fd.hydration)}${choiceField('Krankenhausverlegung','ffHospital',fd.hospital)}${textareaField('Weitere konkrete Festlegungen','ffMedicalOther',fd.medicalOther||'')}</div><div class="form-card"><h3>Werte & Vertrauensperson</h3>${agentFields(p,fd)}${textareaField('Persönliche Wertvorstellungen / religiöse oder sonstige Wünsche','ffValues',fd.values||'')}</div>`}
function formBetreuung(p,fd){return `${commonIdentityFields(p)}${agentFields(p,fd)}<div class="form-card"><h3>Betreuungswünsche</h3>${field('Diese Person soll keinesfalls Betreuer/in werden','ffExclude',fd.exclude||'')}${textareaField('Wünsche zu Wohnen, Pflege und persönlicher Lebensführung','ffCareWishes',fd.careWishes||'')}${textareaField('Weitere Hinweise an Gericht / Betreuung','ffNotes',fd.notes||'')}</div>`}
function formBank(p,fd){return `${commonIdentityFields(p)}${agentFields(p,fd)}<div class="form-card"><h3>Bank / Konten</h3>${field('Bank / Kreditinstitut','ffBankName',fd.bankName||'')}${field('IBAN oder Kontohinweis','ffIban',fd.iban||'','text','Optional. Bei mehreren Konten können diese in den Hinweisen ergänzt werden.')}${selectField('Vollmacht über den Tod hinaus','ffAfterDeath',fd.afterDeath||'no',['no|Nein','yes|Ja','unsure|Noch offen'])}${textareaField('Umfang / Einschränkungen','ffNotes',fd.notes||'')}</div><div class="notice"><b>Bankhinweis:</b> Viele Kreditinstitute verlangen eigene Vollmachtsformulare oder eine Legitimation. Dieses Dokument dient deshalb auch als vorbereiteter Datensatz für die Bank.</div>`}
function formSchweigepflicht(p,fd){return `${commonIdentityFields(p)}${agentFields(p,fd)}<div class="form-card"><h3>Umfang der Entbindung</h3>${selectField('Behandelnde Stellen','ffProviders',fd.providers||'all',['all|Alle behandelnden Ärztinnen/Ärzte und Einrichtungen','named|Nur ausdrücklich genannte Stellen'])}${textareaField('Genannte Ärztinnen/Ärzte / Einrichtungen','ffNamedProviders',fd.namedProviders||'')}${checkLine('ffDiagnosis','Diagnosen und Befunde',fd.diagnosis)}${checkLine('ffTreatment','Behandlung und Therapie',fd.treatment)}${checkLine('ffMedication','Medikation',fd.medication)}${checkLine('ffCare','Pflege- und Entlassungsplanung',fd.care)}${textareaField('Einschränkungen / Zweck','ffNotes',fd.notes||'')}</div>`}
function formBestattung(p,fd){const b=p.bestattung||{};return `${commonIdentityFields(p)}<div class="form-card"><h3>Bestattungswünsche</h3>${selectField('Bestattungsart','ffFuneralType',fd.funeralType||b.type||'',['|Noch offen','Erdbestattung','Feuerbestattung','Seebestattung','Baumbestattung','Andere'])}${field('Gewünschter Friedhof / Ort','ffFuneralPlace',fd.funeralPlace||b.place||'')}${field('Bestatter / Vorsorgevertrag','ffUndertaker',fd.undertaker||b.undertaker||'')}${textareaField('Trauerfeier, Musik, Blumen, Kleidung, Anzeigen','ffCeremony',fd.ceremony||b.ceremony||'')}${textareaField('Weitere Wünsche','ffNotes',fd.notes||b.notes||'')}</div>`}
function formOrgane(p,fd){return `${commonIdentityFields(p)}<div class="form-card"><h3>Entscheidung zur Organ- und Gewebespende</h3>${selectField('Entscheidung','ffOrganDecision',fd.organDecision||'',['|Bitte auswählen','yes|Ja, grundsätzlich einverstanden','no|Nein, nicht einverstanden','limited|Nur bestimmte Organe/Gewebe','delegate|Eine andere Person soll entscheiden'])}${textareaField('Einschränkungen / bestimmte Organe oder Gewebe','ffOrganLimits',fd.organLimits||'')}${agentFields(p,fd)}</div>`}
function formTestament(p,fd){return `${commonIdentityFields(p)}<div class="notice"><b>Vorbereitungsblatt – kein fertiges Testament:</b> Die Angaben werden bewusst nicht als unterschriftsfertiges Testament ausgegeben.</div><div class="form-card"><h3>Erbwünsche vorbereiten</h3>${textareaField('Personen / Institutionen, die bedacht werden sollen','ffHeirs',fd.heirs||'')}${textareaField('Besondere Vermächtnisse / Gegenstände','ffLegacies',fd.legacies||'')}${textareaField('Wünsche zu Ersatzerben / Bedingungen / Testamentsvollstreckung','ffTestamentNotes',fd.testamentNotes||'')}${field('Geplanter Aufbewahrungsort','ffTestamentStorage',fd.testamentStorage||'')}</div>`}
function checkLine(id,label,on){return `<label class="checkline"><input type="checkbox" id="${id}" ${on?'checked':''}> ${esc(label)}</label>`}
function choiceField(label,id,val=''){return selectField(label,id,val||'',['|Bitte auswählen','want|Ich wünsche diese Maßnahme','refuse|Ich lehne diese Maßnahme ab','palliative|Nur zur Symptomlinderung / palliativ','individual|Individuell – siehe weitere Festlegungen'])}
function applyFormContact(){const p=activePerson(),id=val('ffContact'),c=(p?.contacts||[]).find(x=>x.id===id);if(!c)return;setVal('ffAgentName',c.name);setVal('ffAgentRole',c.role);setVal('ffAgentPhone',c.phone);setVal('ffAgentEmail',c.email);if(c.address)setVal('ffAgentAddress',c.address);refreshFormPreview()}
function setVal(id,v){const e=document.getElementById(id);if(e)e.value=v||''}
function collectFilledForm(){const k=state.docKey||'vorsorge';const common={firstName:val('ffFirst'),lastName:val('ffLast'),birthDate:val('ffBirth'),street:val('ffStreet'),zip:val('ffZip'),city:val('ffCity')};const agent={contactId:val('ffContact'),agentName:val('ffAgentName'),agentRole:val('ffAgentRole'),agentPhone:val('ffAgentPhone'),agentEmail:val('ffAgentEmail'),agentAddress:val('ffAgentAddress')};if(k==='vorsorge')return {...common,...agent,health:checked('ffHealth'),residence:checked('ffResidence'),assets:checked('ffAssets'),authorities:checked('ffAuthorities'),post:checked('ffPost'),digital:checked('ffDigital'),court:checked('ffCourt'),afterDeath:val('ffAfterDeath'),notes:val('ffNotes')};if(k==='patienten')return {...common,...agent,situations:val('ffSituations'),pain:val('ffPain'),resuscitation:val('ffResuscitation'),ventilation:val('ffVentilation'),nutrition:val('ffNutrition'),hydration:val('ffHydration'),hospital:val('ffHospital'),medicalOther:val('ffMedicalOther'),values:val('ffValues')};if(k==='betreuung')return {...common,...agent,exclude:val('ffExclude'),careWishes:val('ffCareWishes'),notes:val('ffNotes')};if(k==='bank')return {...common,...agent,bankName:val('ffBankName'),iban:val('ffIban'),afterDeath:val('ffAfterDeath'),notes:val('ffNotes')};if(k==='schweigepflicht')return {...common,...agent,providers:val('ffProviders'),namedProviders:val('ffNamedProviders'),diagnosis:checked('ffDiagnosis'),treatment:checked('ffTreatment'),medication:checked('ffMedication'),care:checked('ffCare'),notes:val('ffNotes')};if(k==='bestattung')return {...common,funeralType:val('ffFuneralType'),funeralPlace:val('ffFuneralPlace'),undertaker:val('ffUndertaker'),ceremony:val('ffCeremony'),notes:val('ffNotes')};if(k==='organe')return {...common,...agent,organDecision:val('ffOrganDecision'),organLimits:val('ffOrganLimits')};if(k==='testament')return {...common,heirs:val('ffHeirs'),legacies:val('ffLegacies'),testamentNotes:val('ffTestamentNotes'),testamentStorage:val('ffTestamentStorage')};return common}
async function saveFilledForm(){const p=activePerson(),k=state.docKey;if(!p||!k)return;const fd=collectFilledForm();p.documents[k]=p.documents[k]||{};p.documents[k].formData=fd;p.documents[k].status='draft';p.documents[k].date=new Date().toISOString().slice(0,10);if(k==='bestattung'){p.bestattung={...(p.bestattung||{}),type:fd.funeralType,place:fd.funeralPlace,undertaker:fd.undertaker,ceremony:fd.ceremony,notes:fd.notes}}await persistPersons();refreshFormPreview();toast('Formular lokal gespeichert')}
function refreshFormPreview(){const p=activePerson();if(!p)return;const e=document.getElementById('formPreview');if(e)e.innerHTML=renderFilledDocument(state.docKey,p,collectFilledForm())}
function printFilledForm(){refreshFormPreview();setTimeout(()=>window.print(),50)}
function personBlock(fd,p){const x=fd&&Object.keys(fd).length?fd:(p.profile||{});return `${esc([x.firstName,x.lastName].filter(Boolean).join(' '))}<br>${x.birthDate?`geb. ${esc(fmtDate(x.birthDate))}<br>`:''}${esc(x.street||'')}<br>${esc([x.zip,x.city].filter(Boolean).join(' '))}`}
function agentBlock(fd){return `${esc(fd.agentName||'Nicht eingetragen')}${fd.agentRole?` (${esc(fd.agentRole)})`:''}<br>${esc(fd.agentAddress||'')}${fd.agentPhone?`<br>Tel.: ${esc(fd.agentPhone)}`:''}${fd.agentEmail?`<br>E-Mail: ${esc(fd.agentEmail)}`:''}`}
function yesno(v){return v==='yes'?'Ja':v==='no'?'Nein':v==='unsure'?'Noch offen':v||'—'}
function choiceText(v){return ({want:'gewünscht',refuse:'abgelehnt',palliative:'nur zur Symptomlinderung / palliativ',individual:'individuell geregelt'})[v]||'nicht festgelegt'}
function boolList(items){return `<ul>${items.filter(x=>x[1]).map(x=>`<li>${esc(x[0])}</li>`).join('')||'<li>Keine Auswahl getroffen</li>'}</ul>`}
function renderFilledDocument(k,p,fd={}){const title=DOCS[k]?.title||'Dokument';let body='';if(k==='vorsorge')body=`<h2>Bevollmächtigte Person</h2><p>${agentBlock(fd)}</p><h2>Umfang</h2>${boolList([['Gesundheitssorge und Pflege',fd.health],['Aufenthalt und Wohnungsangelegenheiten',fd.residence],['Vermögensangelegenheiten',fd.assets],['Behörden, Versicherungen und Sozialleistungsträger',fd.authorities],['Post, Telekommunikation und digitale Kommunikation',fd.post],['Digitaler Nachlass und Online-Konten',fd.digital],['Vertretung gegenüber Gerichten im zulässigen Umfang',fd.court]])}<p><b>Geltung über den Tod hinaus:</b> ${esc(yesno(fd.afterDeath))}</p><p><b>Besondere Wünsche / Einschränkungen:</b><br>${nl(fd.notes)}</p>`;else if(k==='patienten')body=`<div class="draft-mark">ENTWURF – vor Unterschrift sorgfältig prüfen</div><h2>Geltungssituationen</h2><p>${nl(fd.situations)}</p><h2>Ärztliche / pflegerische Maßnahmen</h2><table><tr><td>Schmerz- und Symptombehandlung</td><td>${esc(choiceText(fd.pain))}</td></tr><tr><td>Wiederbelebung</td><td>${esc(choiceText(fd.resuscitation))}</td></tr><tr><td>Künstliche Beatmung</td><td>${esc(choiceText(fd.ventilation))}</td></tr><tr><td>Künstliche Ernährung</td><td>${esc(choiceText(fd.nutrition))}</td></tr><tr><td>Künstliche Flüssigkeitszufuhr</td><td>${esc(choiceText(fd.hydration))}</td></tr><tr><td>Krankenhausverlegung</td><td>${esc(choiceText(fd.hospital))}</td></tr></table><h2>Weitere Festlegungen</h2><p>${nl(fd.medicalOther)}</p><h2>Vertrauensperson</h2><p>${agentBlock(fd)}</p><h2>Wertvorstellungen</h2><p>${nl(fd.values)}</p>`;else if(k==='betreuung')body=`<p>Für den Fall, dass eine rechtliche Betreuung erforderlich wird, wünsche ich folgende Person als Betreuer/in:</p><p>${agentBlock(fd)}</p><p><b>Nicht als Betreuer/in gewünscht:</b> ${esc(fd.exclude||'—')}</p><h2>Wünsche zu Wohnen, Pflege und Lebensführung</h2><p>${nl(fd.careWishes)}</p><h2>Weitere Hinweise</h2><p>${nl(fd.notes)}</p>`;else if(k==='bank')body=`<h2>Bevollmächtigte Person</h2><p>${agentBlock(fd)}</p><p><b>Kreditinstitut:</b> ${esc(fd.bankName||'—')}<br><b>IBAN/Kontohinweis:</b> ${esc(fd.iban||'—')}<br><b>Über den Tod hinaus:</b> ${esc(yesno(fd.afterDeath))}</p><h2>Umfang / Einschränkungen</h2><p>${nl(fd.notes)}</p><p class="fineprint">Hinweis: Das Kreditinstitut kann eigene Vollmachtsformulare oder zusätzliche Legitimation verlangen.</p>`;else if(k==='schweigepflicht')body=`<p>Ich entbinde die ${fd.providers==='named'?'nachfolgend genannten':'mich behandelnden'} Ärztinnen, Ärzte und Einrichtungen gegenüber folgender Person von der Schweigepflicht:</p><p>${agentBlock(fd)}</p>${fd.providers==='named'?`<p><b>Genannte Stellen:</b><br>${nl(fd.namedProviders)}</p>`:''}<h2>Umfasste Informationen</h2>${boolList([['Diagnosen und Befunde',fd.diagnosis],['Behandlung und Therapie',fd.treatment],['Medikation',fd.medication],['Pflege- und Entlassungsplanung',fd.care]])}<h2>Einschränkungen / Zweck</h2><p>${nl(fd.notes)}</p>`;else if(k==='bestattung')body=`<p><b>Gewünschte Bestattungsart:</b> ${esc(fd.funeralType||'Noch offen')}<br><b>Friedhof / Ort:</b> ${esc(fd.funeralPlace||'—')}<br><b>Bestatter / Vorsorgevertrag:</b> ${esc(fd.undertaker||'—')}</p><h2>Trauerfeier</h2><p>${nl(fd.ceremony)}</p><h2>Weitere Wünsche</h2><p>${nl(fd.notes)}</p>`;else if(k==='organe')body=`<p><b>Entscheidung:</b> ${esc(({yes:'Ja, grundsätzlich einverstanden',no:'Nein, nicht einverstanden',limited:'Nur bestimmte Organe/Gewebe',delegate:'Eine andere Person soll entscheiden'})[fd.organDecision]||'Nicht festgelegt')}</p><p><b>Einschränkungen:</b><br>${nl(fd.organLimits)}</p>${fd.organDecision==='delegate'?`<h2>Entscheidungsperson</h2><p>${agentBlock(fd)}</p>`:''}`;else if(k==='testament')body=`<div class="draft-mark">VORBEREITUNGSBLATT – KEIN TESTAMENT</div><h2>Bedachte Personen / Institutionen</h2><p>${nl(fd.heirs)}</p><h2>Vermächtnisse / Gegenstände</h2><p>${nl(fd.legacies)}</p><h2>Weitere Erbwünsche</h2><p>${nl(fd.testamentNotes)}</p><p><b>Geplanter Aufbewahrungsort:</b> ${esc(fd.testamentStorage||'—')}</p>`;return `<article class="generated-form"><header><div class="form-brand">Sterbefall Assistent Deutschland</div><h1>${esc(title)}</h1><p>für</p><div class="identity-box">${personBlock(fd,p)}</div></header>${body}<div class="signature"><div>Ort, Datum</div><div>Unterschrift</div></div><footer>Erstellt mit Sterbefall Assistent Deutschland · lokal auf dem Gerät · ${new Date().toLocaleDateString('de-DE')}</footer></article>`}
function nl(v){return esc(v||'—').replace(/\n/g,'<br>')}

function medical(){const p=activePerson();if(!p)return noPerson('Medizin & Krankenhaus');const m=p.medical||{};return `<section class="screen">${appTop('Medizin & Krankenhaus',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}<div class="form-card"><h3>Behandelnde Stellen</h3>${field('Hausarzt / Praxis','doctorName',m.doctorName)}${field('Telefon Hausarzt','doctorPhone',m.doctorPhone,'tel')}${field('Bevorzugtes Krankenhaus / Klinik','hospital',m.hospital)}</div><div class="form-card"><h3>Hinweise für den Ernstfall</h3>${textareaField('Wichtige medizinische Hinweise','medicalNotes',m.notes,'Nur Informationen eintragen, die im Notfall tatsächlich hilfreich sind.')}${textareaField('Allergien / Unverträglichkeiten','allergies',m.allergies)}${textareaField('Wichtige Medikamente','medications',m.medications)}${field('Aufbewahrungsort Medikamentenplan','medPlan',m.medPlan)}</div><div class="form-card"><h3>Krankenhaus & Auskunft</h3><label class="checkline"><input type="checkbox" id="medicalContactAllowed" ${m.contactAllowed?'checked':''}> Vertrauenspersonen sollen im Ernstfall schnell auffindbar sein</label><label class="checkline"><input type="checkbox" id="organDecision" ${m.organDecision?'checked':''}> Eine Organspende-Entscheidung wurde dokumentiert</label><button class="cta ghost full mt10" onclick="openOfficial('organspende')">Organspende-Register öffnen ↗</button></div><button class="cta teal full" onclick="saveMedical()">Speichern</button></div></section>`}
async function saveMedical(){const p=activePerson();p.medical={doctorName:val('doctorName'),doctorPhone:val('doctorPhone'),hospital:val('hospital'),notes:val('medicalNotes'),allergies:val('allergies'),medications:val('medications'),medPlan:val('medPlan'),contactAllowed:checked('medicalContactAllowed'),organDecision:checked('organDecision')};await persistPersons();toast('Medizinische Hinweise gespeichert');render()}

function zvr(){const p=activePerson();if(!p)return noPerson('Zentrales Vorsorgeregister');const z=p.zvr||{};return `<section class="screen">${appTop('Zentrales Vorsorgeregister',`Für ${personName(p)}`)}<div class="content"><div class="info-card"><div class="big-icon">🏛️</div><h2>ZVR</h2><p>Dokumentiere hier, ob und wann Vorsorgeangelegenheiten beim Zentralen Vorsorgeregister registriert wurden.</p></div><div class="form-card"><label class="checkline"><input type="checkbox" id="zvrRegistered" ${z.registered?'checked':''}> Registrierung wurde vorgenommen</label>${field('Datum der Registrierung','zvrDate',z.date||'','date')}${field('Akten-/Registrierhinweis','zvrRef',z.reference||'','text','Optional; keine Zugangsdaten oder Passwörter speichern.')}${field('Aufbewahrungsort Originale','zvrStorage',z.storageLocation||'')}</div><button class="cta teal full" onclick="saveZvr()">Speichern</button><button class="cta teal full mt10" onclick="openOfficialPdf('zvrP')">📄 Amtliches Formular P automatisch befüllen</button><div class="row mt10"><button class="cta ghost full" onclick="openOfficial('zvr')">Online registrieren ↗</button><button class="cta ghost full" onclick="openOfficial('zvrForms')">Formulare ↗</button></div><div class="notice" style="margin-top:14px">Die Registrierung ersetzt das eigentliche Vorsorgedokument nicht. Für jede vorsorgende Person ist eine eigene Registrierung erforderlich.</div></div></section>`}
async function saveZvr(){const p=activePerson();p.zvr={registered:checked('zvrRegistered'),date:val('zvrDate'),reference:val('zvrRef'),storageLocation:val('zvrStorage')};await persistPersons();toast('ZVR-Status gespeichert');render()}

function bestattung(){const p=activePerson();if(!p)return noPerson('Bestattungswünsche');const b=p.bestattung||{};return `<section class="screen">${appTop('Bestattungswünsche',`Für ${personName(p)}`)}<div class="content"><div class="form-card"><h3>Grundwünsche</h3>${selectField('Bestattungsart','burialType',b.type||'',['|Noch nicht festgelegt','Erdbestattung','Feuerbestattung','Seebestattung','Baumbestattung / Friedwald','Andere'])}${field('Gewünschter Ort / Friedhof','burialPlace',b.place)}${field('Bestatter / Vorsorgevertrag','undertaker',b.undertaker)}${field('Vertrags-/Vorsorgenummer','burialContract',b.contractNo)}</div><div class="form-card"><h3>Trauerfeier & persönliche Wünsche</h3>${textareaField('Musik, Redner, Kleidung, Blumen, Spendenwunsch …','burialCeremony',b.ceremony)}${textareaField('Grab / Urne / weitere Wünsche','burialNotes',b.notes)}</div><button class="cta teal full" onclick="saveBestattung()">Wünsche speichern</button><div class="notice" style="margin-top:14px">Bestattungswünsche sollten für Angehörige auffindbar sein. Ein Testament wird häufig erst nach der Bestattung eröffnet und ist deshalb kein idealer alleiniger Aufbewahrungsort für kurzfristige Bestattungswünsche.</div></div></section>`}
async function saveBestattung(){const p=activePerson();p.bestattung={type:val('burialType'),place:val('burialPlace'),undertaker:val('undertaker'),contractNo:val('burialContract'),ceremony:val('burialCeremony'),notes:val('burialNotes')};if(p.bestattung.type||p.bestattung.notes)p.documents.bestattung={...(p.documents.bestattung||{}),status:'available'};await persistPersons();toast('Bestattungswünsche gespeichert');render()}

function digital(){const p=activePerson();if(!p)return noPerson('Digitaler Nachlass');const d=p.digital||{};return `<section class="screen">${appTop('Digitaler Nachlass',`Für ${personName(p)}`)}<div class="content"><div class="notice"><b>Keine Passwörter im Klartext speichern.</b> Dokumentiere stattdessen, wo ein Passwortmanager, Notfallzugang oder versiegelte Zugangsliste zu finden ist.</div><div class="form-card"><h3>Vertrauensperson</h3>${field('Verantwortliche Person','digitalContact',d.contactName)}${field('Telefon / Kontakt','digitalContactPhone',d.contactPhone)}${field('Ort der Zugangsinformationen','digitalStorage',d.storageLocation,'text','Zum Beispiel: Passwortmanager mit Notfallzugriff, versiegelter Umschlag im Tresor.')}</div><div class="form-card"><h3>Konten & Geräte</h3>${textareaField('Wichtige Dienste','digitalServices',d.services,'Zum Beispiel E-Mail, Apple/Google, Social Media, PayPal, Domains, Cloudspeicher.')}${textareaField('Geräte / Zugangshinweise','digitalDevices',d.devices,'Nur Hinweise, keine PINs oder Passwörter.')}${textareaField('Wünsche','digitalWishes',d.wishes,'Konten löschen, memorialisieren, Daten sichern, Domains übertragen …')}</div><button class="cta teal full" onclick="saveDigital()">Speichern</button></div></section>`}
async function saveDigital(){const p=activePerson();p.digital={contactName:val('digitalContact'),contactPhone:val('digitalContactPhone'),storageLocation:val('digitalStorage'),services:val('digitalServices'),devices:val('digitalDevices'),wishes:val('digitalWishes')};await persistPersons();toast('Digitaler Nachlass gespeichert');render()}

function emergency(){const p=activePerson();if(!p)return noPerson('Notfallkarte');normalizePerson(p);const x=p.profile||{},m=p.medical||{},ecs=(p.contacts||[]).filter(c=>c.isEmergency).slice(0,3);return `<section class="emergency"><button class="cta ghost no-print" onclick="go('home')">‹ Zurück</button><div class="emergency-head"><div class="emergency-symbol">⚠</div><h1>NOTFALL</h1><p>Wichtige Informationen für ${esc(personName(p))}</p></div><div class="emergency-card"><h3>Notfallkontakte</h3>${ecs.length?ecs.map(c=>`<div class="contact-line"><div><b>${esc(c.name)}</b><div class="muted">${esc(c.role||'')}</div></div><span>${esc(c.phone||'')}</span></div>`).join(''):'<p>Noch kein Notfallkontakt hinterlegt.</p>'}</div><div class="emergency-card"><h3>Vorsorge</h3><div class="kv"><b>Patientenverfügung</b><span>${isDocDone(p,'patienten')?'Vorhanden':'Nicht hinterlegt'}</span><b>Aufbewahrungsort</b><span>${esc(p.documents.patienten?.storageLocation||'Nicht hinterlegt')}</span><b>Vorsorgevollmacht</b><span>${isDocDone(p,'vorsorge')?'Vorhanden':'Nicht hinterlegt'}</span><b>ZVR</b><span>${p.zvr?.registered?'Registriert':'Nicht als registriert markiert'}</span></div></div><div class="emergency-card"><h3>Medizin</h3><div class="kv"><b>Hausarzt</b><span>${esc(m.doctorName||'Nicht hinterlegt')}</span><b>Telefon</b><span>${esc(m.doctorPhone||'')}</span><b>Allergien</b><span>${esc(m.allergies||'Keine Angaben')}</span><b>Medikamente</b><span>${esc(m.medications||'Keine Angaben')}</span></div></div><div class="emergency-card"><h3>Person</h3><div class="kv"><b>Name</b><span>${esc(personName(p))}</span><b>Geburtsdatum</b><span>${esc(fmtDate(x.birthDate))}</span><b>Krankenkasse</b><span>${esc(x.healthInsurance||'Nicht hinterlegt')}</span></div></div></section>`}

function serious(){const p=activePerson();if(!p)return noPerson('Schwere Erkrankung');normalizePerson(p);const tasks=[['Patientenverfügung auffindbar?',isDocDone(p,'patienten'),'documents'],['Vorsorgevollmacht vorhanden?',isDocDone(p,'vorsorge'),'documents'],['Vertrauenspersonen erreichbar?',(p.contacts||[]).length>0,'trusted'],['Hausarzt / Behandler hinterlegt?',!!p.medical?.doctorName,'medical'],['Medikamentenplan und Hinweise geklärt?',!!p.medical?.medPlan||!!p.medical?.medications,'medical'],['Bestattungswünsche bei Bedarf besprochen?',!!p.bestattung?.type||!!p.bestattung?.notes,'bestattung']];return `<section class="screen">${appTop('Schwere Erkrankung',`Für ${personName(p)}`)}<div class="content">${personSwitch(p)}<div class="notice"><b>Dieser Bereich ist eine Organisationshilfe.</b> Akute medizinische Beschwerden gehören in professionelle medizinische Versorgung; im Notfall 112.</div><div class="section-title"><h2>Jetzt prüfen</h2></div><div class="list">${tasks.map(t=>task(t[0],t[1],t[1]?'Erledigt / hinterlegt':'Noch offen',t[2])).join('')}</div><div class="form-card mt16"><h3>Gesprächs- und Organisationspunkte</h3><ul class="plain-list"><li>Wer soll medizinische Gespräche begleiten?</li><li>Wo liegen Vollmachten und Originaldokumente?</li><li>Welche Pflege- oder Unterstützungsangebote werden benötigt?</li><li>Welche Verträge, Haustiere, Kinder oder laufenden Verpflichtungen müssen organisiert werden?</li><li>Wer soll informiert werden, wenn sich die Situation verschlechtert?</li></ul></div></div></section>`}

function caseScreen(){const current=state.cases[0]||{},opts=state.persons.map(p=>`<option value="${p.id}" ${current.personId===p.id?'selected':''}>${esc(personName(p))} – ${esc(relationLabel(p.relation))}</option>`).join('');return `<section class="screen">${appTop('Sterbefall','Geführte Fallakte')}<div class="content"><div class="form-card"><h3>Fall</h3><div class="field"><label>Person</label><select id="casePerson"><option value="">Bitte auswählen</option>${opts}</select></div>${field('Sterbedatum','cDeath',current.deathDate,'date')}${selectField('Sterbeort','cPlace',current.place||'',['|Bitte auswählen','Zuhause','Krankenhaus','Pflegeheim','Hospiz','Ausland','Sonstiges'])}<button class="cta teal full" onclick="saveCase()">Fall speichern / aktualisieren</button></div>${current.personId?caseDashboard(current):'<div class="empty-card"><div class="empty-icon">🕯️</div><h3>Noch kein Fall angelegt</h3><p>Wähle eine bereits vorhandene Person aus. Stammdaten werden automatisch übernommen.</p></div>'}</div></section>`}
function caseDashboard(c){const p=state.persons.find(x=>x.id===c.personId);if(!p)return '';const done=c.tasks||{};const phases=[['first','Sofort / heute'],['week','Erste Tage'],['estate','Nachlass & Verträge'],['later','Später']];const items={first:[['doctor','Ärztliche Feststellung / Todesbescheinigung klären'],['relatives','Nahe Angehörige informieren'],['undertaker','Bestatter auswählen / informieren']],week:[['cert','Sterbeurkunden organisieren'],['employer','Arbeitgeber / Rentenstelle informieren'],['health','Krankenkasse informieren'],['insurance','Versicherungen prüfen']],estate:[['will','Testament / Nachlassgericht prüfen'],['bank','Banken und Konten klären'],['home','Wohnung / Immobilie sichern'],['contracts','Verträge und Abos erfassen']],later:[['tax','Steuerliche Themen prüfen'],['digital','Digitalen Nachlass bearbeiten'],['archive','Unterlagen und Fallakte abschließen']]};return `<div class="case-hero"><small>Fallakte</small><h2>${esc(personName(p))}</h2><div>${c.deathDate?`† ${fmtDate(c.deathDate)}`:''}${c.place?` · ${esc(c.place)}`:''}</div></div>${phases.map(([pk,label])=>`<div class="section-title"><h2>${label}</h2></div><div class="list">${items[pk].map(([id,label2])=>caseTask(id,label2,!!done[id])).join('')}</div>`).join('')}<button class="cta ghost full mt16" onclick="go('generator')">✍ Schreiben aus Falldaten erstellen</button>`}
function caseTask(id,label,done){return `<button class="list-item ${done?'done':''}" onclick="toggleCaseTask('${id}')"><div class="dot">${done?'✓':''}</div><div class="grow"><b>${esc(label)}</b><div class="meta">${done?'Erledigt':'Antippen zum Abhaken'}</div></div></button>`}
async function saveCase(){const personId=val('casePerson');if(!personId){toast('Bitte Person auswählen');return}const old=state.cases[0]||{};state.cases=[{...old,id:old.id||uid('case'),personId,deathDate:val('cDeath'),place:val('cPlace'),tasks:old.tasks||{}}];await idbSet('cases','main',state.cases);toast('Fall gespeichert');render()}
async function toggleCaseTask(id){const c=state.cases[0];if(!c)return;c.tasks=c.tasks||{};c.tasks[id]=!c.tasks[id];await idbSet('cases','main',state.cases);render()}

function generator(){const c=state.cases[0],deceased=c?state.persons.find(x=>x.id===c.personId):null,sender=activePerson()||state.persons.find(p=>p.relation==='self')||deceased;if(!deceased)return `<section class="screen">${appTop('Schreiben erstellen')}<div class="content"><div class="notice">Bitte zuerst einen Sterbefall anlegen.</div><button class="cta teal full mt10" onclick="go('case')">Sterbefall öffnen</button></div></section>`;return `<section class="screen">${appTop('Schreiben erstellen',`Falldaten von ${personName(deceased)}`)}<div class="content"><div class="form-card"><h3>Vorlage</h3>${selectField('Schreiben','template','death',['death|Mitteilung über Sterbefall','cancel|Kündigung wegen Todesfall','record|Bitte um schriftliche Bestätigung'])}${field('Empfänger / Organisation','recipient','')}${field('Vertrags- / Kundennummer','contractNo','')}<button class="cta teal full" onclick="updatePreview()">Vorschau aktualisieren</button></div><div class="section-title"><h2>Vorschau</h2><button onclick="window.print()">Drucken / PDF</button></div><div id="preview" class="preview">${esc(buildLetter('death','', '',deceased,c,sender))}</div><div class="notice mt10">Das Schreiben ist eine editierbare Organisationshilfe und keine rechtliche Einzelfallberatung.</div></div></section>`}
function buildLetter(type,recipient,contractNo,p,c,sender){const sx=sender?.profile||{},senderName=personName(sender),senderBlock=[senderName,sx.street,[sx.zip,sx.city].filter(Boolean).join(' ')].filter(Boolean).join('\n'),deathDate=fmtDate(c?.deathDate),birth=fmtDate(p.profile?.birthDate);let body='';if(type==='death')body=`hiermit teile ich Ihnen mit, dass ${personName(p)}${birth?`, geboren am ${birth}`:''}${deathDate?`, am ${deathDate}`:''} verstorben ist.\n\nBitte teilen Sie mir mit, welche Unterlagen Sie für die Bearbeitung benötigen.`;if(type==='cancel')body=`hiermit bitte ich um Beendigung des bestehenden Vertrags${contractNo?` mit der Nummer ${contractNo}`:''} aufgrund des Todes von ${personName(p)}${deathDate?` zum ${deathDate}`:''}.\n\nBitte bestätigen Sie die Bearbeitung schriftlich und informieren Sie mich über noch benötigte Nachweise.`;if(type==='record')body=`bezugnehmend auf den Sterbefall von ${personName(p)} bitte ich um eine schriftliche Bestätigung des Bearbeitungsstands und um Mitteilung, falls noch Unterlagen erforderlich sind.`;return `${senderBlock}\n\n${recipient||'[Empfänger]'}\n\nBetreff: ${type==='cancel'?'Vertrag wegen Todesfall':'Mitteilung Sterbefall'}\n\nSehr geehrte Damen und Herren,\n\n${body}\n\nMit freundlichen Grüßen\n\n${senderName}`}
function updatePreview(){const c=state.cases[0],p=c?state.persons.find(x=>x.id===c.personId):null,s=activePerson()||state.persons.find(x=>x.relation==='self')||p;if(!p)return;document.getElementById('preview').textContent=buildLetter(val('template')||'death',val('recipient'),val('contractNo'),p,c,s)}


function openOfficialPdf(key){state.officialPdfKey=key;go('official-pdf')}
function officialPdfScreen(){
 const p=activePerson();if(!p)return noPerson('Amtliches PDF');
 const key=state.officialPdfKey||'vorsorge',def=OFFICIAL_PDFS[key];if(!def)return noPerson('Amtliches PDF');
 return `<section class="screen">${appTop('Blanko-PDF',`Für ${personName(p)}`)}<div class="content">
 <div class="info-card"><div class="big-icon">📄</div><h2>${esc(def.title)}</h2><p>${esc(def.source)} · Vorlagenstand ${esc(def.stand)}</p></div>
 <div class="notice"><b>Offline & local first:</b> Die App verwendet bevorzugt die im App-Paket gespeicherte Blanko-PDF unter <code>${esc(def.local)}</code>. Personen- und Formulardaten verlassen den Browser nicht.</div>
 <div class="form-card mt16"><h3>Blanko-Vorlage aus der App</h3><p class="muted small">Die Blanko-PDF ist direkt im App-Paket enthalten und funktioniert auch ohne Internet.</p><button class="cta teal full" onclick="fillOfficialPdfBundled()">Blanko-PDF öffnen & automatisch befüllen</button><button class="cta ghost full mt10" onclick="openBundledBlank()">Blanko anzeigen</button></div>
 <div class="form-card"><h3>Vorlage prüfen / aktualisieren</h3><p class="muted small">Über die Quellen-Schaltfläche kann die aktuelle offizielle Information bzw. Originalvorlage kontrolliert werden.</p><button class="cta ghost full" onclick="window.open('${def.url}','_blank','noopener')">Quelle / Original prüfen ↗</button></div>
 <div class="form-card"><h3>Eigene Original-PDF verwenden</h3><div class="field"><label>PDF auswählen</label><input type="file" id="officialPdfFile" accept="application/pdf,.pdf"></div><button class="cta ghost full" onclick="fillOfficialPdfFromFile()">Ausgewählte PDF befüllen</button><button class="cta ghost full mt10" onclick="installTemplateFromFile()">Als lokale Blanko-Vorlage speichern</button></div>
 <div id="pdfStatus" class="pdf-status">Noch keine PDF verarbeitet.</div>
 </div></section>`
}
function openBundledBlank(){const def=OFFICIAL_PDFS[state.officialPdfKey||'vorsorge'];window.open(def.local,'_blank','noopener')}
async function installTemplateFromFile(){
 const key=state.officialPdfKey||'vorsorge',f=document.getElementById('officialPdfFile')?.files?.[0];
 if(!f){toast('Bitte zuerst eine PDF auswählen');return}
 if(f.type && f.type!=='application/pdf'){toast('Bitte eine PDF-Datei auswählen');return}
 const bytes=await f.arrayBuffer();
 await idbSet('templates',key,{name:f.name,bytes,installedAt:new Date().toISOString(),size:f.size});
 toast('Blanko-Vorlage lokal gespeichert');
 const status=document.getElementById('pdfStatus');if(status)status.innerHTML=`<b>Vorlage lokal installiert.</b><br>${esc(f.name)} · ${Math.round(f.size/1024)} KB`;
}
async function getInstalledTemplate(key){return await idbGet('templates',key)}
async function fillOfficialPdfBundled(){
 const key=state.officialPdfKey||'vorsorge',def=OFFICIAL_PDFS[key],status=document.getElementById('pdfStatus');
 try{
   if(status)status.textContent='Lokale Blanko-Vorlage wird geladen …';
   const installed=await getInstalledTemplate(key);
   if(installed?.bytes){await fillOfficialPdfBytes(installed.bytes,installed.name||def.title);return}
   const r=await fetch(def.local,{cache:'no-store'});if(!r.ok)throw new Error(`Lokale Vorlage fehlt (${r.status})`);
   await fillOfficialPdfBytes(await r.arrayBuffer(),def.title)
 } catch(e){if(status)status.innerHTML=`<b>Lokale Blanko-PDF konnte nicht geladen werden.</b><br>Datei: <code>${esc(def.local)}</code><br>Bitte prüfen, ob beim Upload auf GitHub auch der Ordner <b>forms</b> vollständig übernommen wurde.`}
}
async function ensurePdfLib(){
 if(window.PDFLib)return true;
 const status=document.getElementById('pdfStatus');if(status)status.textContent='PDF-Modul wird geladen …';
 return new Promise(resolve=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js';sc.integrity='sha512-z8IYLHO8bTgFqj+yrPyIJnzBDf7DDhWwiEsk4sY+Oe6J2M+WQequeGS7qioI5vT6rXgVRb4K1UVQC5ER7MKzKQ==';sc.crossOrigin='anonymous';sc.onload=()=>resolve(!!window.PDFLib);sc.onerror=()=>resolve(false);document.head.appendChild(sc);});
}
function splitStreet(v=''){const m=String(v).trim().match(/^(.*?)(?:\s+(\d+[a-zA-Z]?[-\/]?\d*[a-zA-Z]?))?$/);return {street:(m?.[1]||v).trim(),house:(m?.[2]||'').trim()}}
function chosenAgent(p){const fd=p.documents?.[state.docKey]?.formData||{};const c=(p.contacts||[]).find(x=>x.id===fd.contactId)||(p.contacts||[]).find(x=>x.isAgent)||(p.contacts||[])[0];if(c)return {name:c.name||'',role:c.role||'',phone:c.phone||'',email:c.email||'',address:c.address||''};return {name:fd.agentName||'',role:fd.agentRole||'',phone:fd.agentPhone||'',email:fd.agentEmail||'',address:fd.agentAddress||''}}
function semanticPdfData(key,p){
 const x=p.profile||{},st=splitStreet(x.street||''),a=chosenAgent(p),ast=splitStreet(a.address||'');
 const an=(a.name||'').trim().split(/\s+/),aFirst=an.length>1?an.slice(0,-1).join(' '):'',aLast=an.length>1?an.at(-1):(a.name||'');
 let docDate='';if(key==='zvrP'){docDate=p.documents?.vorsorge?.date||p.documents?.betreuung?.date||p.documents?.patienten?.date||''}
 return {owner:{first:x.firstName||'',last:x.lastName||'',birth:x.birthDate||'',birthPlace:x.birthPlace||'',street:st.street,house:st.house,zip:x.zip||'',city:x.city||'',phone:x.phone||'',email:x.email||'',country:'Deutschland'},agent:{first:aFirst,last:aLast,name:a.name||'',street:ast.street,house:ast.house,phone:a.phone||'',email:a.email||''},docDate};
}
function normFieldName(n=''){return String(n).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ')}
function pickTextValue(name,data,counters){
 const n=normFieldName(name),agent=/bevoll|vertrauens|betreuer|bevollmachtigte|bevollmaechtigte|vertret/.test(n);
 const person=agent?data.agent:data.owner;
 const has=(...xs)=>xs.some(x=>n.includes(x));
 if(has('vorname'))return person.first||'';
 if(has('nachname','familienname'))return person.last||'';
 if((/\bname\b/.test(n)||n.endsWith(' name'))&&!has('vorname','geburtsname','kontoinhaber')){const idx=counters.name++;return idx===0?data.owner.last:(data.agent.last||data.agent.name)}
 if(has('geburtsdatum'))return agent?'':data.owner.birth;
 if(has('geburtsort'))return agent?'':data.owner.birthPlace;
 if(has('strasse','straße'))return person.street||'';
 if(has('hausnummer','hausnr'))return person.house||'';
 if(has('postleitzahl','plz'))return person.zip||'';
 if(/\bort\b/.test(n)&&!has('geburtsort','aufbewahrungsort'))return person.city||'';
 if(has('telefon','telefonnummer','rufnummer'))return person.phone||'';
 if(has('mail','email','e mail'))return person.email||'';
 if(has('land'))return agent?'':data.owner.country;
 if(has('datum der vorsorge','datum vorsorge','vorsorgeverfugung'))return data.docDate||'';
 return '';
}
async function fillOfficialPdfBytes(bytes,sourceName='Original-PDF'){
 const status=document.getElementById('pdfStatus');
 try{
  if(!await ensurePdfLib())throw new Error('PDF-Modul konnte nicht geladen werden. Bitte Internetverbindung prüfen.');
  const {PDFDocument}=window.PDFLib,pdf=await PDFDocument.load(bytes,{ignoreEncryption:true}),form=pdf.getForm(),fields=form.getFields(),p=activePerson(),key=state.officialPdfKey||'vorsorge',data=semanticPdfData(key,p),counters={name:0};
  let filled=0,checks=0,unknown=[];
  for(const f of fields){
   const name=f.getName();
   try{
    if(typeof f.setText==='function'){
      const v=pickTextValue(name,data,counters);if(v){f.setText(String(v));filled++}else unknown.push(name);
    } else if(typeof f.check==='function'){
      const n=normFieldName(name);let yes=false;
      if(key==='zvrP'){
        if(n.includes('vorsorgevollmacht')&&isDocDone(p,'vorsorge'))yes=true;
        if(n.includes('betreuungsverfugung')&&isDocDone(p,'betreuung'))yes=true;
        if(n.includes('patientenverfugung')&&isDocDone(p,'patienten'))yes=true;
      }
      if(yes){f.check();checks++}
    }
   }catch(e){}
  }
  try{form.updateFieldAppearances()}catch(e){}
  const out=await pdf.save(),blob=new Blob([out],{type:'application/pdf'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`${key}-${(personName(p)||'person').replace(/[^a-z0-9äöüß]+/gi,'-')}-amtlich-ausgefüllt.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(u),4000);
  if(status)status.innerHTML=`<b>Fertig.</b> ${filled} Textfelder und ${checks} Auswahlfelder wurden automatisch befüllt. ${unknown.length?`${unknown.length} Felder konnten nicht eindeutig zugeordnet werden und bleiben zur Kontrolle offen.`:'Alle erkannten Felder wurden verarbeitet.'}`;
 }catch(e){if(status)status.innerHTML=`<b>PDF konnte nicht verarbeitet werden.</b><br>${esc(e.message||String(e))}`;}
}
async function fillOfficialPdfFromWeb(){const def=OFFICIAL_PDFS[state.officialPdfKey||'vorsorge'],status=document.getElementById('pdfStatus');try{if(status)status.textContent='Amtliche Originalvorlage wird geladen …';const r=await fetch(def.url,{mode:'cors',cache:'no-store'});if(!r.ok)throw new Error(`Abruf fehlgeschlagen (${r.status})`);await fillOfficialPdfBytes(await r.arrayBuffer(),def.title)}catch(e){if(status)status.innerHTML=`<b>Direkter Abruf wurde vom Behördenserver oder Browser blockiert.</b><br>Bitte über „Original öffnen“ die PDF speichern und anschließend unten auswählen. Deine Daten wurden nicht übertragen.`}}
async function fillOfficialPdfFromFile(){const f=document.getElementById('officialPdfFile')?.files?.[0];if(!f){toast('Bitte zuerst eine PDF auswählen');return}await fillOfficialPdfBytes(await f.arrayBuffer(),f.name)}

function backup(){return `<section class="screen">${appTop('Datensicherung','Local-first bleibt nur sicher, wenn es ein Backup gibt')}<div class="content"><div class="info-card"><div class="big-icon">💾</div><h2>Lokales Backup</h2><p>Exportiere regelmäßig eine Sicherungsdatei. Sie enthält persönliche und möglicherweise sensible Daten.</p></div><button class="cta teal full" onclick="exportData()">Backup exportieren</button><div class="form-card mt16"><h3>Backup wiederherstellen</h3><div class="field"><label>JSON-Sicherungsdatei</label><input type="file" id="importFile" accept="application/json,.json"></div><button class="cta ghost full" onclick="importData()">Backup importieren</button></div><div class="notice"><b>Sicherheit:</b> Die exportierte Datei ist in dieser Version noch nicht verschlüsselt. Bewahre sie geschützt auf. Eine passwortgeschützte verschlüsselte Sicherung ist für die nächste Ausbaustufe vorgesehen.</div></div></section>`}
function exportData(){const data={app:'Sterbefall Assistent Deutschland',version:5,exportedAt:new Date().toISOString(),persons:state.persons,cases:state.cases,settings:state.settings};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`sterbefall-assistent-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Backup erstellt')}
async function importData(){const f=document.getElementById('importFile')?.files?.[0];if(!f){toast('Bitte Backup-Datei auswählen');return}try{const data=JSON.parse(await f.text());if(!Array.isArray(data.persons))throw new Error('Ungültiges Backup');if(!confirm('Vorhandene lokale Daten durch dieses Backup ersetzen?'))return;state.persons=data.persons.map(normalizePerson);state.cases=Array.isArray(data.cases)?data.cases:[];state.settings=data.settings||state.settings;state.activePersonId=state.persons[0]?.id||null;await persistAll();toast('Backup wiederhergestellt');go('home')}catch(e){toast('Backup konnte nicht gelesen werden')}}

function val(id){return document.getElementById(id)?.value?.trim()||''}
function checked(id){return !!document.getElementById(id)?.checked}
async function persistPersons(){state.persons=state.persons.map(normalizePerson);await idbSet('persons','main',state.persons);await saveMeta()}
async function persistAll(){await persistPersons();await idbSet('cases','main',state.cases);await idbSet('settings','main',state.settings)}
async function saveMeta(){await idbSet('meta','main',{activePersonId:state.activePersonId,dataVersion:5})}
async function migrateLegacy(){let existing=await idbGet('persons','main');if(existing?.length){state.persons=existing.map(normalizePerson);return}const oldProfile=await idbGet('profile','main')||{},oldDocs=await idbGet('docs','main')||{};if(Object.keys(oldProfile).length||Object.keys(oldDocs).length){const p=normalizePerson({id:uid('person'),relation:'self',profile:{...oldProfile},documents:{...oldDocs},contacts:[]});if(oldProfile.emergencyName||oldProfile.emergencyPhone)p.contacts=[{id:uid('contact'),name:oldProfile.emergencyName||'',role:oldProfile.emergencyRelation||'',phone:oldProfile.emergencyPhone||'',isEmergency:true,isAgent:false}];delete p.profile.emergencyName;delete p.profile.emergencyRelation;delete p.profile.emergencyPhone;state.persons=[p];state.activePersonId=p.id;await persistPersons()}}
async function init(){db=await openDB();await migrateLegacy();if(!state.persons.length)state.persons=(await idbGet('persons','main')||[]).map(normalizePerson);const meta=await idbGet('meta','main')||{};state.activePersonId=meta.activePersonId||state.activePersonId||state.persons[0]?.id||null;state.cases=await idbGet('cases','main')||[];state.settings=await idbGet('settings','main')||state.settings;render();if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}

Object.assign(window,{go,back,newPerson,editPerson,selectPerson,deletePerson,savePersonBasic,saveProfile,addContact,removeContact,openDoc,saveDocumentDetail,openOfficial,openOfficialPdf,openBundledBlank,fillOfficialPdfBundled,installTemplateFromFile,fillOfficialPdfFromWeb,fillOfficialPdfFromFile,applyFormContact,saveFilledForm,refreshFormPreview,printFilledForm,saveMedical,saveZvr,saveBestattung,saveDigital,saveCase,toggleCaseTask,updatePreview,exportData,importData});
